pipeline:
flowchart TB
  S["samples<br/>raw readings"] --> N["nights<br/>sleep window, medians"]
  Q["analysis_queue<br/>work waiting"] -.->|"runs every minute"| N
  N --> B["baselines<br/>normal from 42 nights"]
  N --> DS["daily_status<br/>points, total, nudge"]
  B --> DS
  SET["score_settings<br/>versioned weights"] -->|"version used"| DS
  DS --> I["insights<br/>shared module output"]
  DS --> O["notifications<br/>outbox"]
  I --> G["digests<br/>weekly summary"]
  classDef raw fill:#FFFFFF,stroke:#3A3A3C,color:#000000;
  classDef cfg fill:#F2F2F7,stroke:#C4C4C8,color:#3A3A3C;
  classDef notify fill:#FFF4E8,stroke:#E6CBAE,color:#8A4100;
  class S raw;
  class SET,Q cfg;
  class O notify;

er_results:
erDiagram
  profiles ||--o{ nights : "one per night"
  nights ||--|{ baselines : "one per reading"
  nights ||--o| daily_status : "scored as"
  score_settings ||--o{ daily_status : "version used"
  daily_status ||--o{ insights : "explained by"
  profiles ||--o{ digests : weekly
  nights {
    date night_date PK
    bool finished
    num sleeping_hr
    num hrv_median
  }
  baselines {
    date night_date PK
    text metric PK
    num median_28
    bool building
  }
  daily_status {
    date date PK
    text status
    jsonb points
    num total
    text nudge
  }
  score_settings {
    int version PK
    jsonb weights
    bool frozen
  }
  insights {
    date date
    text module
    text severity
  }
  digests {
    date week_start PK
    jsonb facts
  }

er_logs:
erDiagram
  profiles ||--o{ usage_events : logs
  profiles ||--o{ events : "owner records"
  profiles ||--o{ analysis_queue : queues
  usage_events {
    text event
    jsonb meta "never health values"
  }
  events {
    date date
    text type
    text source
  }
  analysis_queue {
    date from_date
    bool send_push
    text status
  }
  experiments {
    text hypothesis
    text status
  }
